// src/components/ChordBlock.js

import React from 'react';
import ChordCard from './ChordCard'; // Импортируем наш новый компонент

const ChordBlock = ({ sequence }) => {
  if (!sequence || sequence.length === 0) return null;

  // Находим уникальные аккорды, чтобы не рисовать дубли
  const uniqueChords = [...new Set(sequence)];

  return (
    <div>
      {/* Блок с названиями аккордов в последовательности */}
      <div className="chord-names">
        {sequence.map((chord, index) => (
          <span key={index} className="chord-box">
            {chord}
          </span>
        ))}
      </div>

      {/* Блоки с аппликатурами для каждого уникального аккорда */}
      <div className="diagrams-container">
        {uniqueChords.map(chordName => (
          <ChordCard key={chordName} chordName={chordName} />
        ))}
      </div>
    </div>
  );
};

export default ChordBlock;
